function eventsView(){return page('Every celebration, together','Dates, venues and little details for each chapter of your wedding.',button('＋ Add celebration','add-event'))+`<div class="event-grid">${[...state.events].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(e=>{const c=eventPalette(e);return `<article class="event-card"><div class="event-card-header" style="--event-color:${c.color};--event-bg:${c.accent}"><span>❋</span><p class="eyebrow">${esc(e.kind)}</p><h2>${esc(e.name)}</h2><p>${fmtDate(e.date)} · ${fmtTime(e.time)}</p></div><div class="event-card-body"><p>⌖ ${esc(e.venue||'Venue to be confirmed')}</p><p>♧ ${esc(e.dress||'Add a dress code')}</p>${e.notes?`<p>${esc(e.notes)}</p>`:''}<div class="card-actions">${button('Edit details','edit-event',true,`data-id="${e.id}"`)}<button class="text-link" data-action="event-design" data-id="${e.id}">Create card →</button><button class="icon-button" data-delete="events" data-id="${e.id}" aria-label="Remove ${esc(e.name)}">×</button></div></div></article>`}).join('')}</div>${!state.events.length?empty('Your first celebration','Add a traditional event or make one of your own.','add-event','Add celebration'):''}`;}
function invitationEvent(){return state.events.find(e=>e.id===selectedInvitationEvent&&e.kind==='Wedding')||state.events.find(e=>e.kind==='Wedding');}
function invitationConfig(){const p=state.profile,e=invitationEvent();if(isLocalUser()){try{const c=JSON.parse(localStorage.getItem('wedcanvas:invitation:v2')||'null');if(c?.partner1===p.partner1&&c?.partner2===p.partner2)savedInvitationDraft=normalizeConfig(c)}catch{}}return normalizeConfig({...savedInvitationDraft,...weddingPreset(selectedInvitationTemplate),partner1:p.partner1,partner2:p.partner2,groomName:p.groomName||'',brideName:p.brideName||'',hostSide:p.hostSide||'groom',date:e?.date||p.date,city:p.city,theme:selectedInvitationTemplate,time:e?.time||'18:00',timezone:'+05:30',venue:e?.venue||'Venue to be confirmed',address:e?.address||p.address||'',reference:p.invitationReference||savedInvitationDraft?.reference||null,photoUrl:p.invitationPhoto||savedInvitationDraft?.photoUrl||'',groomPhoto:p.groomPhoto||savedInvitationDraft?.groomPhoto||'',bridePhoto:p.bridePhoto||savedInvitationDraft?.bridePhoto||'',venuePhotoUrl:e?.venuePhoto||'',events:weddingPreset(selectedInvitationTemplate).events,dressCode:e?.dress||'',rsvpContact:p.rsvpContact||'',audioUrl:p.invitationAudio||'',audioName:p.invitationAudioName||'',ganeshIcon:p.ganeshIcon||'none',music:true,scratch:true});}
function invitationUpload(key,label,url){return `<label class="photo-upload">${label}${url?`<img src="${esc(url)}" alt="${label}">`:''}<input type="file" accept="image/jpeg,image/png,image/webp" data-invite-upload="${key}" aria-label="Upload ${label.toLowerCase()}"><small>JPG, PNG or WebP · any size · we make it fast for you</small></label>${url?`<button class="text-link" data-action="remove-invite-photo" data-key="${key}">Remove ${label.toLowerCase()}</button>`:''}`;}
function invitationView(){const themeEntries=ownedEntries(Object.entries(weddingThemes));selectedInvitationTemplate=ownedPick(invitationEvent()?.invitationTheme||themeForEvent(invitationEvent()?.kind),themeEntries);previewConfig=invitationConfig();const hash='#card='+encodeConfig(previewConfig),e=invitationEvent();return page('Your wedding, beautifully invited','Full reference invitation. Edit every photograph, story, event and message, then preview the cinematic opening.',`<a class="button" href="studio${isLocalUser()?'?demo=1':''}${hash}">Edit all photos, text & events ↗</a>`)+`<div class="studio-layout"><div class="studio-window"><div class="window-header"><span>Interactive guest preview</span><button class="text-link" data-action="replay">↺ Replay</button></div><iframe id="studio-frame" src="invite${hash}" title="Your touch-to-open wedding invitation" allow="autoplay"></iframe></div><aside><section class="panel">${select('invitationEvent','Celebration',state.events.filter(e=>e.kind==='Wedding').map(e=>[e.id,e.name]),e?.id)}<p class="field-help">Wedding date, venue and invitation style.</p></section>${themeEntries.length>1?`<div class="invitation-theme-grid">${themeEntries.map(([key,t],index)=>`<button class="template-card ${selectedInvitationTemplate===key?'active':''}" data-template="${key}" aria-pressed="${selectedInvitationTemplate===key}"><img src="${referenceDesignFor(key).scene}" alt="${t.name}"><span>${String(index+1).padStart(2,'0')} · ${t.name}<small>${key==='premium-original'?'PREMIUM · Original source design':'Complete wedding invitation'}</small></span></button>`).join('')}</div>`:`<section class="panel your-design"><p class="eyebrow">YOUR DESIGN</p><h3>${themeEntries[0][1].name}</h3><p class="field-help">The design you chose. The preview shows it; use the options below to add your photographs.</p></section>`}<section class="panel invitation-photo-controls"><h3>Your invitation photographs</h3>${select('invitationGanesh','Ganesh icon · optional',Object.entries(ganeshOptions),state.profile.ganeshIcon||'none')}<p class="field-help">Your selected icon appears at the top of the invitation.</p>${invitationUpload('couple','Couple photo',state.profile.invitationPhoto)}<div class="photo-upload song-upload"><label>Your wedding song<input type="file" data-invite-song accept="audio/mpeg,audio/mp3,audio/wav,audio/x-wav,audio/ogg,audio/mp4,audio/x-m4a" aria-label="Upload wedding song"></label><small>MP3, WAV, OGG or M4A · up to 20 MB</small><p role="status">${esc(state.profile.invitationAudioName||'Upload a song for your guests to hear.')}</p>${state.profile.invitationAudio?button('Remove song','remove-invite-song',true):''}${state.profile.invitationAudio?.startsWith('local-audio:')?'<p class="field-help">Song saved on this device. Sign in and upload to share across devices.</p>':''}</div>${invitationUpload('venue','Venue photo',e?.venuePhoto)}<p class="field-help">These photos are visible to people who can open the invitation link. Private profile photos stay in your workspace.</p></section><div class="panel"><h3>${esc(e?.name||'Your celebration')}</h3><p class="quiet" style="margin:15px 0">${fmtDate(e?.date||state.profile.date)}<br>${esc(e?.venue||state.profile.city)}</p>${button('Copy invitation link','copy-invite')}<p class="field-help" style="margin-top:15px">Your shareable link unlocks when this design is yours. The preview above is always free.</p></div></aside></div>`;}
function designsView(){if(!selectedDesignEvent&&state.events.length){selectedDesignEvent=state.events[0].id;selectedTemplate=themeForEvent(selectedEvent()?.kind);}selectedTemplate=ownedPick(selectedTemplate,ownedEntries(Object.entries(eventThemes)));return page('Little keepsakes. Big moments.','Create a personalized digital card or event poster from your wedding details.',button('Import a design','import-design',true))+`<div class="design-layout"><section class="panel design-controls"><p class="eyebrow">CREATE AN EVENT DESIGN</p><h2 style="margin-bottom:22px">Made for your celebration</h2>${select('designEvent','Celebration',state.events.map(e=>[e.id,e.name]),selectedEvent()?.id)}${select('designFormat','Format',['Digital card','Poster'],selectedFormat)}${select('designLayout','Layout',[['heirloom','Heirloom Frame'],['portrait','Portrait Spotlight'],['editorial','Editorial']],selectedLayout)}${select('designTheme','Art direction',ownedEntries(Object.entries(eventThemes)).map(([key,t])=>[key,t.name+' · '+t.event]),selectedTemplate)}${select('nameFont1',state.profile.partner1+' · name font',Object.entries(nameFontStyles).map(([k,f])=>[k,f.label]),selectedEvent()?.nameFont1||'classic')}${select('nameFont2',state.profile.partner2+' · name font',Object.entries(nameFontStyles).map(([k,f])=>[k,f.label]),selectedEvent()?.nameFont2||'classic')}<p class="field-help">Choose each name’s lettering independently. Saved per celebration, for both cards and posters.</p>${cardPhotoControl()}<div class="opacity-control"><label for="background-photo-opacity">Background photo opacity <output id="opacity-value" for="background-photo-opacity">${Math.round(photoBackgroundOpacity(selectedEvent())*100)}%</output></label><input id="background-photo-opacity" name="backgroundPhotoOpacity" type="range" min="0" max="100" step="1" value="${Math.round(photoBackgroundOpacity(selectedEvent())*100)}" aria-describedby="opacity-help"><div class="opacity-endpoints"><span>Invisible</span><span>Full strength</span></div><p id="opacity-help" class="field-help">Controls the background photo only. Main portraits keep their original clarity. Your preview updates after generation.</p></div><p class="quiet" style="font-size:14px;margin:18px 0">Use a different couple photo for each event. Layout and art direction are independent choices.</p>${button('Generate my design','generate-design')}${button('Create an AI variation','ai-variation',true)}${button('Download PNG','download-design',true,generatedCanvas?'':'disabled')}${button('Save to my designs','save-design',true,generatedCanvas?'':'disabled')}<p class="field-help">Instant template generation in Easy Wedding. For a new AI-created design, use the AI design assistant.</p></section><div><div id="design-stage" class="design-stage">${empty('Your next beautiful keepsake','Choose your celebration and generate a personalized design.')}</div><p class="design-info">${selectedFormat==='Poster'?'1080 × 1350':'1080 × 1520'} px · Ready to download</p></div></div><section class="panel" style="margin-top:25px"><div class="panel-heading"><h2>Your design collection</h2><span class="quiet">${state.designs.length} saved</span></div>${state.designs.length?`<div class="design-gallery">${state.designs.map(d=>`<article>${d.mode==='video'?`<video src="${esc(d.url)}" controls playsinline preload="metadata" aria-label="${esc(d.name)}"></video>`:`<img src="${esc(d.url)}" alt="${esc(d.name)}">`}<p>${esc(d.name)}</p><small>${esc(d.format)}</small><div class="card-actions"><button class="text-link" data-action="download-saved" data-id="${d.id}">Download</button><button class="text-link" data-delete="designs" data-id="${d.id}">Remove</button></div></article>`).join('')}</div>`:empty('A collection of your celebrations','Your generated and imported designs will appear here.')}</section>`;}
function wardrobeView(){const w=wardrobe[selectedWardrobe];return page('Dress every moment','Event-by-event ideas for the bride and groom. Save the pieces you love.',button('＋ Add shopping item','add-shopping'))+`<div class="section-tabs" role="group" aria-label="Outfit event">${Object.keys(wardrobe).map(e=>`<button class="chip ${selectedWardrobe===e?'active':''}" data-wardrobe="${e}" aria-pressed="${selectedWardrobe===e}">${e}</button>`).join('')}</div><div class="wardrobe-layout"><div class="wardrobe-image"><img class="wardrobe-art" src="assets/${w.image}" alt="${esc(selectedWardrobe)} outfit inspiration: ${esc(w.bride)} and ${esc(w.groom)}"><p class="art-caption">AI-created style inspiration · Not a product listing</p></div><div class="wardrobe-copy"><div class="panel"><p class="eyebrow">THE ${selectedWardrobe.toUpperCase()} EDIT</p><h2>${w.mood}</h2><p>${w.detail}</p><div class="swatches" aria-label="Suggested colours"><span style="background:${w.color}"></span><span style="background:${w.accent}"></span><span style="background:#c09a54"></span><span style="background:#f8eddb"></span></div>${[['Bride',w.bride],['Groom',w.groom]].map(([person,outfit])=>`<div class="outfit-person"><p class="eyebrow">FOR THE ${person.toUpperCase()}</p><h3>${outfit}</h3><button class="button secondary small" data-action="save-outfit" data-person="${person}">＋ Save to shopping list</button></div>`).join('')}<p class="source-note">Styling references: <a href="https://www.manyavar.com/en-in/blogs/grooms-guide-to-wedding-attire-india.html" target="_blank" rel="noopener">Manyavar groom guide</a> and <a href="https://www.manyavar.com/en-in/mohey/lehenga" target="_blank" rel="noopener">Mohey occasion wear</a>. Adapt to your traditions and comfort.</p></div></div></div><section class="panel shopping-list"><div class="panel-heading"><h2>Your shopping list</h2><span class="quiet">${state.shopping.filter(i=>i.done).length} of ${state.shopping.length} bought</span></div>${state.shopping.length?state.shopping.map(i=>`<div class="list-row"><label class="check-label"><input type="checkbox" data-shopping="${i.id}" ${i.done?'checked':''}><span><strong>${esc(i.title)}</strong><small>${esc(i.event)} · ${esc(i.person)} · ${rupees(i.budget)} budget</small></span></label><div class="row-actions"><button class="text-link" data-edit="shopping" data-id="${i.id}">Edit</button><button class="text-link" data-delete="shopping" data-id="${i.id}">Remove</button></div></div>`).join(''):empty('Your wedding wardrobe starts here','Save an outfit idea or add a piece you already have in mind.','add-shopping','Add shopping item')}</section>`;}
function budgetView(){const t=budgetTotals(state);return page('Room for every little detail','Plan in INR, add your own costs and keep track of payments.',button('＋ Add cost','add-budget')+button('Download PDF','pdf',true))+`<div class="stats-grid">${stat('Estimated total',rupees(t.total),`Includes ${state.profile.contingency}% contingency`,'₹')}${stat('Paid so far',rupees(t.paid),'Payments you have recorded','✓')}${stat('Balance to plan for',rupees(t.remaining),'Estimated total less recorded payments','◷')}${stat(t.unallocated>=0?'Budget remaining':'Over your budget',rupees(Math.abs(t.unallocated)),`${rupees(state.profile.budget)} target`,'◈')}</div><section class="panel"><div class="panel-heading"><h2>Your wedding estimate</h2><button class="text-link" data-action="budget-starter">Add blank planning categories</button></div>${state.budget.length?`<div class="budget-table-wrap"><table class="budget-table"><thead><tr><th>Cost / category</th><th class="numeric">Quantity</th><th class="numeric">Rate</th><th class="numeric">Estimate</th><th class="numeric">Paid</th><th>Actions</th></tr></thead><tbody>${state.budget.map(b=>`<tr><td>${esc(b.title)}<small>${esc(b.category)}${b.notes?' · '+esc(b.notes):''}</small></td><td class="numeric">${b.quantity}</td><td class="numeric">${rupees(b.rate)}</td><td class="numeric">${rupees(b.quantity*b.rate)}</td><td class="numeric">${rupees(b.paid)}</td><td><button class="text-link" data-edit="budget" data-id="${b.id}">Edit</button> <button class="text-link" data-delete="budget" data-id="${b.id}">Remove</button></td></tr>`).join('')}</tbody><tfoot><tr><td colspan="3">Subtotal</td><td class="numeric">${rupees(t.subtotal)}</td><td colspan="2"></td></tr><tr><td colspan="3">Contingency (${state.profile.contingency}%)</td><td class="numeric">${rupees(t.contingency)}</td><td colspan="2"></td></tr></tfoot></table></div><div class="table-total"><span>Total estimate</span><strong>${rupees(t.total)}</strong></div><div class="card-actions" style="justify-content:flex-end;margin-bottom:23px">${button('＋ Add more','add-budget',true)}</div>`:empty('Start with what matters most','Add venue hire, catering per guest, pandal, lighting and any other cost.','add-budget','Add your first cost')}<p class="field-help">These are your planning figures, not live vendor quotes. Enter tax-inclusive rates or add taxes as a separate cost. Shopping and vendor quotes are added to this estimate only when you choose to add them.</p></section><div class="two-col"><section class="panel"><h3>Make space for surprises</h3><p class="quiet" style="margin:14px 0">Your contingency is ${state.profile.contingency}% of the estimate. Change it and your budget target in your wedding profile.</p>${button('Edit budget settings','profile',true)}</section><section class="panel"><h3>A plan worth keeping</h3><p class="quiet" style="margin:14px 0">Download a wedding PDF with your event schedule, complete estimate and a designed cover page with an artistic background.</p>${button('Download wedding PDF','pdf')}</section></div>`;}
function vendorsView(){return page('Your vendor directory','Keep every vendor, quote and booking in one private place — saved with your wedding, no outside lookup needed.',button('＋ Add vendor','add-vendor'))+`<section class="panel"><div class="filter-bar">${field('vendorQ','Search vendors',vendorFilter.q,'text','id="vendor-q" maxlength="150" placeholder="Name, area or note…"')}${select('vendorCategory','Service',[['','All services'],...categories],vendorFilter.category)}${select('vendorStatus','Booking status',[['','All statuses'],'Shortlisted','Quote requested','In discussion','Booked','Completed'],vendorFilter.status)}</div><div id="vendor-grid">${vendorGridHtml()}</div><p class="map-note">Vendors are saved only in your wedding workspace. Confirm prices and availability with each vendor directly; this website does not place a reservation.</p></section><div class="panel-heading"><h2>Your wedding team</h2><span class="quiet" id="vendor-count">${state.vendors.length} saved · ${state.vendors.filter(vendorMatches).length} shown</span></div>${state.vendors.length?'':empty('Build your vendor directory','Add your photographer, caterer, decorator, pandal house and every helping hand — with quotes, deposits and booking status.','add-vendor','Add your first vendor')}`;}
function tasksView(){const done=state.tasks.filter(t=>t.done).length;return page('A little closer, every day','Keep track of the work, the people helping and the dates that matter.',button('＋ Add task','add-task'))+`<section class="panel"><div class="panel-heading"><h2>Your wedding checklist</h2><span class="quiet">${done} / ${state.tasks.length} complete</span></div><div class="progress"><span style="width:${state.tasks.length?done/state.tasks.length*100:0}%"></span></div>${state.tasks.length?[...state.tasks].sort((a,b)=>Number(a.done)-Number(b.done)||a.due.localeCompare(b.due)).map(t=>taskRow(t).replace('</div></div>','</div></div>')).join(''):empty('Every detail has its place','Add a task and choose who will look after it.','add-task','Add task')}</section>`;}
function cardPhotoControl(){const e=selectedEvent();return `<label class="photo-upload">Couple photo for ${esc(e?.name||'this event')}${e?.cardPhoto?`<img src="${esc(e.cardPhoto)}" alt="Couple photo for ${esc(e.name)}">`:''}<input type="file" data-card-photo="true" accept="image/jpeg,image/png,image/webp" aria-label="Upload couple photo for this card"><small>Private photo · JPG, PNG or WebP · any size · we make it fast for you</small></label>${e?.cardPhoto?button('Remove event photo','remove-card-photo',true):''}`;}
function creativePrompt(){const e=selectedEvent();if(!e)return 'Add a wedding event to prepare your brief.';const t=eventThemes[aiStyle]||eventThemes[themeForEvent(e.kind)],base=designPrompt(state,e,selectedFormat,aiStyle);if(aiMode==='image')return base.replace('Use the uploaded couple photographs faithfully without changing their facial features.',aiReference==='event'&&(e.cardPhoto||state.profile.invitationPhoto)?'Use the selected joint couple reference photo faithfully.':state.profile.photo1||state.profile.photo2?'Preserve the identity of every provided partner photograph. Do not invent a missing reference.':'No reference photos are selected. Create celebration artwork without inventing likenesses of the couple.')+'\nSelected art direction: '+t.name+' — '+t.mood+'.\nComposition: '+selectedLayout+' layout.\nAdditional requirements: '+(aiRequirements||'None.');return `Create a cinematic Indian ${e.name} invitation video using the two uploaded reference portraits.\nPartner one / reference 1: ${state.profile.partner1}; partner two / reference 2: ${state.profile.partner2}. Image 1 and image 2 identify these two people. Preserve each person's facial identity, skin tone and natural proportions; do not merge their faces or invent additional people.\nArt direction: ${t.name}; ${t.mood}. Premium realistic materials, natural fabric movement, restrained particles, believable depth and warm volumetric light.\nFormat: ${aiOrientation==='landscape'?'horizontal 16:9':'vertical 9:16'}, highest quality and duration supported by my account. Aim for one short coherent clip, approximately 8 seconds if supported.\nShot plan: opening 0–25% — macro detail of the event decor, slow cinematic push-in; 25–65% — elegant reveal of the couple in event-appropriate Indian attire, subtle natural smiles and gentle camera orbit; 65–100% — pull back to the venue-inspired composition and leave calm negative space for invitation lettering. Use smooth transitions and realistic depth of field.\nCelebration details: ${e.name}, ${e.date}, ${e.time} IST, ${e.venue||'venue not provided'}, ${state.profile.city}. Do not invent an address or venue. If precise lettering is unreliable, leave clean space for the event details to be added afterward.\nAudio: tasteful instrumental Indian celebration music; no unrequested speech or lip-sync.\nAvoid distorted hands, face drift, flashing light, cartoon styling, clutter and rapid cuts.\nRequirements: ${aiRequirements||'Follow the selected design direction.'}\nIf two reference photos or this video format are unsupported, explain the limitation before generation; do not silently ignore a reference.`;}
function aiPhoto(key,label){const p=state.profile;return `<div class="ai-photo-item"><label class="ai-photo">${p[key]?`<img src="${esc(p[key])}" alt="${label}">`:'<span class="ai-photo-empty">＋</span>'}<strong>${label}</strong><input type="file" data-upload="${key}" accept="image/jpeg,image/png,image/webp" aria-label="Upload ${label.toLowerCase()}"><small>JPG / PNG / WebP · any size · we make it fast for you</small></label>${p[key]?`<button class="text-link" data-remove-photo="${key}">Remove ${label.toLowerCase()} photo</button>`:''}</div>`;}
function aiView(){if(!aiPrompt){aiStyle=ownedPick(themeForEvent(selectedEvent()?.kind),ownedEntries(Object.entries(eventThemes)));aiPrompt=creativePrompt();}aiStyle=ownedPick(aiStyle,ownedEntries(Object.entries(eventThemes)));return page('Your imagination. Your creative account.','Create event artwork or a cinematic video from your own couple photographs.','','EASY WEDDING CREATIVE STUDIO')+`<div class="creative-layout"><section class="panel creative-controls"><div class="section-tabs" role="group" aria-label="Generation type"><button class="chip ${aiMode==='image'?'active':''}" data-ai-mode="image" aria-pressed="${aiMode==='image'}">Invitation image</button><button class="chip ${aiMode==='video'?'active':''}" data-ai-mode="video" aria-pressed="${aiMode==='video'}">Gemini video</button></div><div class="form-grid">${select('aiEvent','Celebration',state.events.map(e=>[e.id,e.name]),selectedEvent()?.id)}${select('aiStyle','Design direction',ownedEntries(Object.entries(eventThemes)).map(([k,t])=>[k,t.name]),aiStyle)}${aiMode==='image'?select('aiFormat','Format',['Digital card','Poster'],selectedFormat):select('aiOrientation','Video orientation',[['portrait','Portrait · 9:16'],['landscape','Landscape · 16:9']],aiOrientation)+'<p class="field-help">Duration and reference limits depend on your Gemini account.</p>'}</div>${aiMode==='image'&&(selectedEvent()?.cardPhoto||state.profile.invitationPhoto)?select('aiReference','Reference photos',[['event',selectedEvent()?.cardPhoto?'Saved couple photo for this event':'Couple photo from your invitation'],['partners','Separate partner photographs']],aiReference):''}${aiMode==='image'&&aiReference==='event'&&(selectedEvent()?.cardPhoto||state.profile.invitationPhoto)?`<div class="photo-upload"><strong>Couple photo · ${esc(selectedEvent().name)}</strong><img src="${esc(selectedEvent().cardPhoto||state.profile.invitationPhoto)}" alt="Saved couple photo for this event"></div>`:''}<h3 class="creative-label">${aiMode==='image'&&aiReference==='event'?'Optional partner photographs · joint photo selected':'Your two reference photographs'}</h3><div class="ai-photos">${aiPhoto('photo1',state.profile.partner1+' / partner one')}${aiPhoto('photo2',state.profile.partner2+' / partner two')}</div><label class="creative-label">Your requirements<textarea id="ai-requirements" rows="3" maxlength="2500" placeholder="For example: a marigold courtyard, a slow couple reveal, no text…">${esc(aiRequirements)}</textarea></label><p class="field-help">Your brief updates when you change the event, design or requirements.</p><div class="provider-options" role="group" aria-label="Creative account">${(aiMode==='video'?['gemini']:['chatgpt','canva','gemini']).map(p=>`<button data-ai-provider="${p}" class="provider-choice ${aiProvider===p?'active':''}" aria-pressed="${aiProvider===p}">${{chatgpt:'ChatGPT',canva:'Canva',gemini:'Gemini'}[p]}</button>`).join('')}</div>${button('Send to my '+({chatgpt:'ChatGPT',canva:'Canva',gemini:'Gemini'}[aiProvider])+' account ↗','send-creative')}<p class="bridge-status" id="bridge-status" role="status">${esc(bridgeStatus)}</p><p class="field-help">Your account opens in a companion window. Review the uploaded photos, choose the image/video tool and click Generate there. Select the finished result or its exported file to return it here.</p></section><aside><section class="panel"><p class="eyebrow">PROFESSIONAL CREATIVE BRIEF</p><h2>${aiMode==='video'?'A scene-by-scene vision':'Every detail, ready'}</h2><label class="creative-label">Edit your prompt<textarea id="ai-prompt" class="prompt-box" maxlength="14000">${esc(aiPrompt)}</textarea></label><div class="card-actions">${button('Refresh prompt','prepare-brief',true)}${button('Copy','copy-brief',true)}${button('Download','download-brief',true)}</div></section><section class="panel companion-setup"><p class="eyebrow">ONE-TIME DESKTOP SETUP</p><h3>Install your creative companion</h3><p>Chrome or Edge on a computer. Use each person’s own provider account; no API key is needed.</p><a class="button secondary" href="downloads/easy-wedding-companion.zip" download>Download companion ZIP</a><details><summary>How to install and connect</summary><ol><li>Extract the downloaded ZIP.</li><li>Open <strong>chrome://extensions</strong> or <strong>edge://extensions</strong>.</li><li>Turn on Developer mode. Choose Load unpacked and select the extracted folder containing manifest.json.</li><li>Reload Easy Wedding, then Send to my account.</li><li>Allow the selected provider in the companion window and sign in directly there.</li></ol><p>For Canva, open its design prompt first. If an image or video cannot be selected, export it and use Return an exported file in the companion.</p></details><p class="field-help">Companion preview: provider screens can change. Live generation on your signed-in accounts has not yet been verified. Video requires an eligible Gemini account. Mobile users can download the brief and import a finished file.</p><div class="card-actions">${button('Check companion','check-companion',true)}${button('Import image / video','import-design',true)}</div></section></aside></div>`;}
function settingsView(){const p=state.profile;return page('The two of you, and every detail','Your profile supplies names, dates and photographs to your designs.')+`<div class="two-col"><section class="panel"><form id="profile-form" class="profile-form"><h2 style="margin-bottom:25px">Your wedding details</h2><div class="form-grid">${profileFields(p)}${field('rsvpContact','RSVP WhatsApp number',p.rsvpContact||'','tel','maxlength="25" placeholder="+91 98765 43210"')}${area('address','Wedding venue address',p.address||'','maxlength="500"')}${area('notes','Notes for your wedding plan',p.notes||'','maxlength="2000"')}</div><div class="dialog-actions"><button class="button" type="submit">Save wedding details</button></div><p class="field-help" style="margin-top:15px">Changing the wedding date does not move existing event dates or task deadlines. Review them in Events and Checklist.</p></form></section><aside><section class="panel"><h2 style="margin-bottom:20px">Your photographs</h2><div class="profile-photos">${[['groomPhoto',p.groomName||'Groom'],['bridePhoto',p.brideName||'Bride']].map(([key,name])=>`<div class="upload-box">${p[key]?`<img src="${esc(p[key])}" alt="${esc(name)}">`:'<span class="avatar" style="width:70px;height:70px;margin:0 auto 15px;font-size:28px">♡</span>'}<strong>${esc(name)}</strong><label><span>Upload photo</span><input type="file" accept="image/jpeg,image/png,image/webp" data-upload="${key}" aria-label="Upload ${esc(name)} photograph"></label>${p[key]?`<button class="text-link" data-remove-photo="${key}">Remove photo</button>`:''}</div>`).join('')}</div><p class="field-help">JPG, PNG or WebP · Any size — we shrink it for you. Used in your cards and the softly faded PDF background. Stored privately with your account.</p></section><section class="panel"><p class="eyebrow">YOUR ACCOUNT</p><h3>${esc(user.name||'Signed-in wedding workspace')}</h3><p class="quiet" style="margin:14px 0;overflow-wrap:anywhere">${esc(user.email)}</p><p class="field-help">Your wedding plan belongs to this account. Design subscriptions are separate.</p><div class="card-actions"><button class="text-link" data-action="retry-save">Save again</button><button class="text-link" data-action="backup">Download backup</button></div>${user.admin?'<a class="text-link" style="display:block;margin-top:20px" href="/boss">Payment admin — gateways, keys &amp; prices</a>':''}<a class="text-link" style="display:block;margin-top:20px" href="rsvps">Guest RSVPs — replies to your invitations</a><a class="text-link" style="display:block;margin-top:8px" href="guests">Personal invitations — a special link for every guest</a><button class="text-link" style="display:block;margin-top:20px" data-action="signout">Sign out</button></section><section class="panel data-panel" id="data-panel"><p class="eyebrow">YOUR DATA</p><h3>Download or delete your data</h3><p class="field-help">It is your data. Download everything we hold about you as one ZIP file, or delete it all permanently.</p>${isLocalUser()?'<p class="field-help"><strong>Demo mode:</strong> this is a sample plan stored only in your browser, so there is nothing on our servers to download or delete.</p>':`<div class="card-actions">${button('Download my data (ZIP)','download-data',true)}</div><details class="danger-zone"><summary>Delete my account and all my data</summary><p><strong>This cannot be undone.</strong> Your account, wedding plan, invitations, photographs, songs, guest replies and bookings are erased from our servers for ever. Payment records we must keep by law are made anonymous. Download your data first if you want a copy.</p><label for="delete-confirm">Type <strong>DELETE</strong> to confirm</label><input id="delete-confirm" type="text" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="DELETE" aria-describedby="delete-help"><p class="field-help" id="delete-help">The button below stays off until you type DELETE exactly.</p><button class="button danger" type="button" id="delete-account" data-action="delete-account" disabled>Delete everything permanently</button></details>`}</section></aside></div>`;}
async function saveProfile(e){e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));for(const k of ['guests','budget','contingency'])values[k]=Number(values[k]);state.profile={...state.profile,...values};applyHostSide(state.profile);changed();await save();render();if(!dirty)toast('Wedding details saved.');}
function openModal(title,fields,submit,saveText='Save changes',addMore=null){modalSubmit=submit;modalAddMore=addMore;$('#dialog-title').textContent=title;$('#dialog-fields').innerHTML=fields;$('#dialog-save').textContent=saveText;$('#dialog-save').disabled=false;$('#dialog-error').hidden=true;const moreBtn=$('#dialog-add-more');if(moreBtn)moreBtn.hidden=!addMore;$('#form-dialog').showModal();}
function edit(kind,id){const old=state[kind].find(x=>x.id===id),item=old||{id:uid()};let fields,title;
 if(kind==='events'){title=old?'Edit celebration':'Add a celebration';fields=field('name','Celebration name',item.name||'','text','required maxlength="100"')+select('kind','Event type',eventKinds,item.kind||'Wedding')+field('date','Date',item.date||state.profile.date,'date','required')+field('time','Time (IST)',item.time||'18:00','time','required')+field('venue','Venue',item.venue||'','text','maxlength="180"')+field('dress','Dress code',item.dress||'','text','maxlength="180"')+area('notes','Little details',item.notes||'','maxlength="1000"');}
 if(kind==='tasks'){title=old?'Edit task':'Add a wedding task';fields=field('title','What needs doing?',item.title||'','text','required maxlength="180"')+select('category','Category',['Planning','Venue','Guests','Vendors','Shopping','Invitations','Budget','Other'],item.category||'Planning')+field('due','Due date',item.due||state.profile.date,'date','required')+field('owner','Who is looking after it?',item.owner||'','text','maxlength="100"')+(old?'<button class="text-link" type="button" data-delete="tasks" data-id="'+item.id+'">Remove this task</button>':'');}
 if(kind==='budget'){title=old?'Edit wedding cost':'Add a wedding cost';fields=field('title','Cost description',item.title||'','text','required maxlength="180"')+select('category','Category',categories,item.category||'Other')+field('quantity','Quantity / guest count',item.quantity??1,'number','required min="0" max="1000000000" step="0.01"')+field('rate','Rate per unit (INR)',item.rate??0,'number','required min="0" max="1000000000" step="0.01"')+field('paid','Already paid (INR)',item.paid??0,'number','required min="0" max="1000000000" step="0.01"')+area('notes','Notes / quote reference',item.notes||'','maxlength="500"');}
 if(kind==='vendors'){title=old?'Update vendor':'Add a vendor';fields=field('name','Business name',item.name||'','text','required maxlength="150"')+select('category','Service',categories,item.category||'Other')+field('area','Area / city',item.area||state.profile.city,'text','maxlength="150"')+field('phone','Phone number',item.phone||'','tel','maxlength="40"')+select('status','Booking status',['Shortlisted','Quote requested','In discussion','Booked','Completed'],item.status||'Shortlisted')+field('quote','Quoted total (INR)',item.quote??0,'number','required min="0" max="1000000000" step="0.01"')+field('deposit','Deposit paid (INR)',item.deposit??0,'number','required min="0" max="1000000000" step="0.01"')+area('notes','Booking date, reference & notes',item.notes||'','maxlength="1200"')+'<p class="field-help wide">This records an arrangement you make with the vendor. Saving does not send a booking request or payment.</p>';}
 if(kind==='shopping'){title=old?'Edit shopping item':'Add a shopping item';fields=field('title','Outfit or accessory',item.title||'','text','required maxlength="180"')+select('event','Celebration',eventKinds,item.event||selectedWardrobe)+select('person','Shopping for',['Bride','Groom','Family','Other'],item.person||'Bride')+field('budget','Your budget (INR)',item.budget??0,'number','required min="0" max="1000000000" step="100"')+area('notes','Size, colour & fitting notes',item.notes||'','maxlength="1000"');}
 openModal(title,fields,values=>{for(const k of ['quantity','rate','paid','quote','deposit','budget'])if(k in values)values[k]=Number(values[k]);if(kind==='budget'&&values.paid>values.quantity*values.rate)throw Error('The payment cannot exceed this cost. Increase the estimate if the quote changed.');if(kind==='vendors'&&values.deposit>values.quote)throw Error('The deposit cannot exceed the quoted total.');const next={...item,...values};if(kind==='tasks'||kind==='shopping')next.done=!!item.done;if(old)state[kind]=state[kind].map(x=>x.id===id?next:x);else state[kind].push(next);changed();render();},old?'Save changes':({budget:'Save cost',events:'Add celebration',tasks:'Add task',vendors:'Save vendor',shopping:'Add shopping item'}[kind]||'Save changes'),(!old&&kind==='budget')?()=>edit('budget'):null);
}
async function upload(file,path='/api/assets'){if(isLocalUser())return await localUpload(file,path);const form=new FormData();form.set('file',file);return await api(path,{method:'POST',body:form});}
function downloadBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.hidden=true;document.body.append(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(u)},30000)}
function backup(){if(!state)return;downloadBlob(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'Easy-Wedding-Backup.json');toast('Wedding backup downloaded.');}
function importDesign(){openModal('Import your finished design',field('name','Design name','','text','required maxlength="150"')+select('format','Format',['Digital card','Poster','AI artwork','AI video'],'AI artwork')+'<label class="wide">Image or video<input name="file" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" required><small class="field-help">Image up to 8 MB, or MP4/WebM video up to '+(isLocalUser()?'1.5 MB in this local demo':'20 MB')+'.</small></label>',async(values,form)=>{const file=form.elements.file.files[0];if(!file||!['image/jpeg','image/png','image/webp','video/mp4','video/webm'].includes(file.type))throw Error('Choose a JPG, PNG, WebP, MP4 or WebM file.');const mode=file.type.startsWith('video/')?'video':'image';if(file.size>(mode==='video'?20:8)*1024*1024)throw Error(mode==='video'?'Choose a video under 20 MB.':'Choose an image under 8 MB.');const result=await upload(file,mode==='video'?'/api/videos':'/api/assets');state.designs.push({id:uid(),name:values.name,mode,format:mode==='video'?'AI video':values.format,url:result.url,created:new Date().toISOString()});changed();go('designs');toast('Design imported to your collection.');},'Import design');}
function currentBrief(){const value=$('#ai-prompt').value.trim();if(!value||value.length>14000)throw Error('Enter a design prompt between 1 and 14,000 characters.');return value;}
const actions={
 'profile':()=>go('settings'),'invitation':()=>go('invitations'),'add-event':()=>edit('events'),'edit-event':el=>edit('events',el.dataset.id),'add-task':()=>edit('tasks'),'add-budget':()=>edit('budget'),'add-vendor':()=>edit('vendors'),'add-shopping':()=>edit('shopping'),'retry-save':save,'backup':backup,'signout':()=>{if(window.EWAuth)window.EWAuth.signOut();},
 'download-data':async el=>{el.disabled=true;const label=el.textContent;el.textContent='Preparing your ZIP…';try{const response=await fetch('/api/account/export',{credentials:'same-origin'});if(!response.ok){const info=await response.json().catch(()=>({}));throw Error(info.error||'We could not prepare your data. Please try again.');}const blob=await response.blob(),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='easy-wedding-my-data.zip';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),30000);toast('Your data download has started.');}catch(error){toast(error.message);}finally{el.disabled=false;el.textContent=label;}},
 'delete-account':async el=>{if($('#delete-confirm')?.value!=='DELETE'){toast('Type DELETE to confirm.');return;}el.disabled=true;el.textContent='Deleting…';try{await api('/api/account/delete',{method:'POST',body:JSON.stringify({confirm:'DELETE'})});try{for(const key of Object.keys(localStorage))if(/wedcanvas|workspace|easywedding|ew[-_]plan/i.test(key)&&key!=='ew_vid')localStorage.removeItem(key);sessionStorage.clear();}catch{}toast('Your account and all your data have been deleted.');setTimeout(()=>location.assign('/'),1200);}catch(error){toast(error.message);el.disabled=false;el.textContent='Delete everything permanently';}},
 'event-design':el=>{selectedDesignEvent=el.dataset.id;selectedTemplate=themeForEvent(selectedEvent()?.kind);generatedCanvas=null;go('designs');},
 'remove-invite-song':()=>{invitationSongVersion++;state.profile.invitationAudio='';state.profile.invitationAudioName='';changed();render();},
 'remove-invite-photo':el=>{if(el.dataset.key==='couple')state.profile.invitationPhoto='';else if(invitationEvent())invitationEvent().venuePhoto='';changed();render();},
 'replay':()=>$('#studio-frame').contentWindow.postMessage({type:'wedcanvas:replay'},location.origin),
 'copy-invite':async()=>{let entitled=false;try{const u=window.EWAuth?.session();if(u&&!u.fake){if(u.admin)entitled=true;else{const r=await fetch('/api/entitlements');if(r.ok){const d=await r.json();entitled=!!d.admin||(d.designs||[]).includes(previewConfig.theme)||(d.designs||[]).includes('ALL');}}}}catch{}if(!entitled){toast('Invitation links unlock after you buy this design. Open the Studio to get your link.');return;}const url=invitationUrl(previewConfig,location.href);try{await navigator.clipboard.writeText(url);toast(previewConfig.audioUrl.startsWith('local-audio:')?'Link copied. Song is stored on this device; sign in and upload to share it with guests.':'Invitation link copied.')}catch{openModal('Your invitation link',area('link','Copy this link',url,'readonly'),()=>{},'Done')}},
 'budget-starter':()=>{const existing=new Set(state.budget.map(x=>x.category));for(const category of categories)if(!existing.has(category))state.budget.push({id:uid(),title:category,category,quantity:category==='Catering'?Number(state.profile.guests):1,rate:0,paid:0,notes:''});changed();render();toast('Blank categories added. Enter your quotes to build the estimate.');},
 'save-outfit':el=>{const person=el.dataset.person,w=wardrobe[selectedWardrobe],title=person==='Bride'?w.bride:w.groom;if(state.shopping.some(x=>x.title===title&&x.event===selectedWardrobe)){toast('This outfit is already on your shopping list.');return}state.shopping.push({id:uid(),title,event:selectedWardrobe,person,budget:0,done:false,notes:w.pieces.join(', ')});changed();render();toast('Outfit saved. Add your budget and fitting notes.');},
 'vendor-budget':el=>{const vendor=state.vendors.find(v=>v.id===el.dataset.id),old=state.budget.find(x=>x.vendorId===vendor.id);if(old){edit('budget',old.id);return}state.budget.push({id:uid(),title:vendor.name,category:vendor.category,quantity:1,rate:Number(vendor.quote),paid:Number(vendor.deposit),notes:'Vendor quote snapshot; update if the quote changes.',vendorId:vendor.id});changed();toast('Vendor quote added to your budget.');},
 'generate-design':async el=>{if(!state.events.length){toast('Add a celebration first.');return}selectedDesignEvent=$('select[name=designEvent]').value;selectedFormat=$('select[name=designFormat]').value;selectedTemplate=$('select[name=designTheme]').value;el.disabled=true;const oldLabel=el.textContent;el.textContent='Creating your design…';try{generatedCanvas=await renderDesign(state,selectedEvent(),selectedFormat,selectedTemplate,selectedLayout);render();toast('Your personalized design is ready.')}finally{el.disabled=false;el.textContent=oldLabel}},
 'download-design':async()=>{if(generatedCanvas){await downloadDesign(generatedCanvas,(selectedEvent()?.name||'Wedding')+'-'+selectedFormat+'.png');toast('Your PNG download has started.');}},
 'save-design':async el=>{if(!generatedCanvas)return;el.disabled=true;try{const blob=await new Promise(r=>generatedCanvas.toBlob(r,'image/png'));const result=await upload(new File([blob],'wedding-design.png',{type:'image/png'}));state.designs.push({id:uid(),name:(selectedEvent()?.name||'Wedding')+' · '+couple(),format:selectedFormat,url:result.url,created:new Date().toISOString()});changed();render();toast('Design saved to your collection.');}finally{el.disabled=false;}},
 'import-design':importDesign,
 'download-saved':async el=>{const d=state.designs.find(x=>x.id===el.dataset.id),r=await fetch(d.url);if(!r.ok)throw Error('The design could not be downloaded.');const blob=await r.blob(),extension=({'image/jpeg':'jpg','image/webp':'webp','image/png':'png','video/mp4':'mp4','video/webm':'webm'})[blob.type]||'png';downloadBlob(blob,d.name.replace(/[^a-zA-Z0-9 -]/g,'')+'.'+extension);},
 'prepare-brief':()=>{aiPrompt=creativePrompt();$('#ai-prompt').value=aiPrompt;toast('Professional prompt refreshed.');},
 'ai-variation':()=>{aiMode='image';aiStyle=selectedTemplate;aiReference=selectedEvent()?.cardPhoto?'event':'partners';aiPrompt=creativePrompt();go('ai');},
 'check-companion':()=>{bridge.check();toast('Checking companion. If it is not detected, install it and reload.');},
 'send-creative':sendCreative,
 'remove-card-photo':()=>{if(selectedEvent())selectedEvent().cardPhoto='';generatedCanvas=null;changed();render();},
 'copy-brief':async()=>{const brief=currentBrief();try{await navigator.clipboard.writeText(brief);toast('Design brief copied.')}catch{$('#ai-prompt').select();toast('Select and copy the highlighted brief.');}},
 'download-brief':()=>downloadBlob(new Blob([currentBrief()],{type:'text/plain;charset=utf-8'}),'Easy-Wedding-Design-Brief.txt'),
 'pdf':async el=>{if(!state){toast('Create your wedding profile first.');return}el.disabled=true;const old=el.innerHTML;el.textContent='Preparing PDF…';try{const blob=await exportWeddingPDF(state);const result=await upload(new File([blob],'Easy-Wedding-Plan.pdf',{type:'application/pdf'}),'/api/exports');toast('Your wedding PDF is ready.');const link=result.url;openModal('Your wedding plan is ready',`<p class="wide">Your PDF includes your events, complete estimate, checklist and a designed cover page.</p><a class="button wide" href="${link}" download="Easy-Wedding-Plan.pdf">Download wedding plan PDF</a>`,()=>{},'Done')}finally{el.disabled=false;el.innerHTML=old}}
};
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;try{
 if(el.matches('a.brand,a.mobile-brand')){if(e.ctrlKey||e.metaKey||e.shiftKey||e.button!==0)return;e.preventDefault();goHome();return;}
 if(el.dataset.aiMode){aiMode=el.dataset.aiMode;if(aiMode==='video')aiProvider='gemini';aiPrompt=creativePrompt();render();return;}if(el.dataset.aiProvider){aiProvider=el.dataset.aiProvider;render();return;}
 if(el.dataset.view){e.preventDefault();go(el.dataset.view);return}
 if(!state&&el.dataset.action!=='signout'&&(el.dataset.action||el.dataset.edit))return;
 if(el.dataset.action&&actions[el.dataset.action])await actions[el.dataset.action](el);
 if(el.dataset.edit)edit(el.dataset.edit,el.dataset.id);
 if(el.dataset.delete){const kind=el.dataset.delete,id=el.dataset.id;confirmAction=()=>{state[kind]=state[kind].filter(x=>x.id!==id);changed();$('#form-dialog').close();render();};$('#confirm-dialog').showModal();}
 if(el.dataset.wardrobe){selectedWardrobe=el.dataset.wardrobe;render();}
 if(el.dataset.template){selectedInvitationTemplate=el.dataset.template;if(invitationEvent()){invitationEvent().invitationTheme=selectedInvitationTemplate;changed();}render();}
 if(el.dataset.provider){const urls={chatgpt:'https://chatgpt.com/',canva:'https://www.canva.com/',gemini:'https://gemini.google.com/app'};const popup=window.open(urls[el.dataset.provider],'wedcanvas-creative','popup,width=900,height=850,left=650,top=30,noopener,noreferrer');toast('Use your own account there, then import the finished image here.');}
 if(el.dataset.removePhoto){state.profile[el.dataset.removePhoto]='';applyHostSide(state.profile);if(view==='ai')aiPrompt=creativePrompt();changed();render();}
 }catch(error){toast(error.message||'Something went wrong. Please try again.');el.disabled=false;}});
let opacityPreviewTimer,opacityPreviewRevision=0;
document.addEventListener('input',e=>{if(e.target.name!=='backgroundPhotoOpacity')return;const event=selectedEvent();if(!event)return;event.backgroundPhotoOpacity=Math.round(Math.max(0,Math.min(100,Number(e.target.value))));$('#opacity-value').textContent=event.backgroundPhotoOpacity+'%';changed();clearTimeout(opacityPreviewTimer);const token=++opacityPreviewRevision;if(!generatedCanvas)return;const controls=[...document.querySelectorAll('[data-action="download-design"],[data-action="save-design"]')];controls.forEach(el=>el.disabled=true);const options=[selectedFormat,selectedTemplate,selectedLayout];opacityPreviewTimer=setTimeout(async()=>{try{const canvas=await renderDesign(state,{...event},...options);if(token!==opacityPreviewRevision||view!=='designs'||selectedEvent()?.id!==event.id||options[0]!==selectedFormat||options[1]!==selectedTemplate||options[2]!==selectedLayout)return;generatedCanvas=canvas;$('#design-stage').replaceChildren(canvas);controls.forEach(el=>el.disabled=false);}catch(error){if(token===opacityPreviewRevision){generatedCanvas=null;toast(error.message);}}},180);});
