document.addEventListener('change',async e=>{const el=e.target;try{if(el.name==='invitationGanesh'){state.profile.ganeshIcon=el.value;changed();render();}if(el.matches('[data-invite-song]')&&el.files?.[0]){el.disabled=true;const file=el.files[0],songVersion=++invitationSongVersion,targetProfile=state.profile;await validateSong(file);if(songVersion!==invitationSongVersion||state.profile!==targetProfile)return;let url;if(isLocalUser())url=await prepareLocalSong(file);else{const data=new FormData();data.set('file',file);const r=await api('/api/invitation-audio',{method:'POST',body:data});url=r.url;}if(songVersion!==invitationSongVersion||state.profile!==targetProfile)return;state.profile.invitationAudio=url;state.profile.invitationAudioName=file.name;changed();render();toast('Wedding song added.');}if(['nameFont1','nameFont2'].includes(el.name)){const event=selectedEvent();if(!event)return;event[el.name]=Object.hasOwn(nameFontStyles,el.value)?el.value:'classic';changed();const regenerate=Boolean(generatedCanvas);generatedCanvas=null;++opacityPreviewRevision;render();if(regenerate)await actions['generate-design']($('[data-action="generate-design"]'));}if(el.name==='invitationEvent'){selectedInvitationEvent=el.value;selectedInvitationTemplate=invitationEvent()?.invitationTheme||themeForEvent(invitationEvent()?.kind);render();}if(el.dataset.inviteUpload&&el.files[0]){el.disabled=true;toast('Uploading your invitation photo…');const targetEvent=invitationEvent();const result=await upload(await compressPhoto(el.files[0]),'/api/invitation-photos');if(el.dataset.inviteUpload==='couple')state.profile.invitationPhoto=result.url;else if(targetEvent)targetEvent.venuePhoto=result.url;changed();render();toast('Invitation photo added.');}if(el.dataset.task){state.tasks.find(t=>t.id===el.dataset.task).done=el.checked;changed();render();}if(el.dataset.shopping){state.shopping.find(t=>t.id===el.dataset.shopping).done=el.checked;changed();}if(el.dataset.upload&&el.files[0]){const cropped=await cropPhoto(el.files[0],{title:el.dataset.upload==='photo1'?'Crop '+(state.profile.partner1||'partner one')+'’s photo':'Crop '+(state.profile.partner2||'partner two')+'’s photo'});if(!cropped){el.value='';return;}el.disabled=true;toast('Uploading your photograph…');const result=await upload(cropped);state.profile[el.dataset.upload]=result.url;applyHostSide(state.profile);if(view==='ai')aiPrompt=creativePrompt();changed();render();toast('Photograph uploaded.');}if(el.name==='aiReference'){aiReference=el.value;aiPrompt=creativePrompt();render();}if(['aiEvent','aiStyle','aiFormat','aiOrientation'].includes(el.name)){if(el.name==='aiEvent'){selectedDesignEvent=el.value;aiStyle=themeForEvent(selectedEvent()?.kind);generatedCanvas=null;}if(el.name==='aiStyle')aiStyle=el.value;if(el.name==='aiFormat'){selectedFormat=el.value;generatedCanvas=null;}if(el.name==='aiOrientation')aiOrientation=el.value;aiPrompt=creativePrompt();render();}if(el.dataset.cardPhoto&&el.files[0]){const event=selectedEvent();if(!event)throw Error('Add an event first.');el.disabled=true;const result=await upload(await compressPhoto(el.files[0]));event.cardPhoto=result.url;generatedCanvas=null;changed();render();toast('Couple photo added to this event card.');}if(['designEvent','designFormat','designTheme','designLayout'].includes(el.name)){selectedDesignEvent=$('select[name=designEvent]').value;selectedFormat=$('select[name=designFormat]').value;selectedLayout=$('select[name=designLayout]').value;selectedTemplate=el.name==='designEvent'?themeForEvent(selectedEvent()?.kind):$('select[name=designTheme]').value;generatedCanvas=null;render();}if(el.name==='vendorCategory'){vendorFilter.category=el.value;renderVendorGrid();}if(el.name==='vendorStatus'){vendorFilter.status=el.value;renderVendorGrid();}}catch(error){toast(error.message);el.disabled=false;if(el.type==='file')el.value='';}});
$('#modal-form').addEventListener('submit',async e=>{e.preventDefault();const addMore=e.submitter&&e.submitter.id==='dialog-add-more'&&modalAddMore;$('#dialog-save').disabled=true;const moreBtn=$('#dialog-add-more');if(moreBtn)moreBtn.disabled=true;try{await modalSubmit(Object.fromEntries(new FormData(e.currentTarget)),e.currentTarget);$('#form-dialog').close();if(addMore){modalAddMore();return;}}catch(error){$('#dialog-error').textContent=error.message;$('#dialog-error').hidden=false;}finally{$('#dialog-save').disabled=false;if(moreBtn)moreBtn.disabled=false;}});
$('#dialog-close').onclick=$('#dialog-cancel').onclick=()=>$('#form-dialog').close();$('#confirm-cancel').onclick=()=>$('#confirm-dialog').close();$('#confirm-remove').onclick=()=>{confirmAction?.();$('#confirm-dialog').close();};$('#menu-button').onclick=()=>{$('.sidebar').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',String($('.sidebar').classList.contains('open')));};$('#backup-button').onclick=backup;
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(views.some(v=>v[0]===next)&&view!==next){view=next;render()}});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
async function boot(){try{
 const demo=new URLSearchParams(location.search).has('demo');
 user=fakeSession();
 if(demo)user={id:'demo',name:'Demo guest',demo:true};
 if(!user){try{user=(await api('/api/session')).user||null;}catch(e){user=null;}}
 if(!user){location.replace('/login?next=%2Fdashboard');return;}
 if(user.demo){const saved=readLocal();state=saved?saved.state:demoPlan();revision=saved?saved.revision:1;$('#save-state').textContent='Demo plan — not linked to an account';const gm=$('#global-message');gm.innerHTML='You are exploring the <strong>live demo</strong> — <a href="/register">Create account</a> to keep your own wedding plan forever.';gm.hidden=false;}
 else if(user.fake){const saved=readLocal();state=saved?saved.state:null;revision=saved?saved.revision:0;$('#save-state').textContent=state?'Saved on this device':'Create your wedding profile';}
 else{const ent=await api('/api/entitlements');ownedDesigns=ent.admin?['ALL']:(ent.designs||[]).filter(id=>!String(id).startsWith('addon-'));if(!ownedDesigns.length){location.replace('/register');return;}const result=await api('/api/workspace');state=result.state;if(state)applyHostSide(state.profile);revision=result.revision;$('#save-state').textContent=state?'All changes saved':'Create your wedding profile';}
 view=views.some(v=>v[0]===location.hash.slice(1))?location.hash.slice(1):'overview';render();}catch(e){if(e&&e.status===401){/* the server session has expired or been revoked: refresh the cached sign-in state, then log in again */try{await window.EWAuth?.refresh?.();}catch(x){}location.replace('/login?next=%2Fdashboard');return;}$('#main-content').innerHTML=page('Your workspace is temporarily unavailable','Your saved wedding plan has not been replaced.')+`<div class="notice error">${esc(e.message)}</div><button class="button" id="retry-load">Try again</button>`;$('#retry-load').onclick=boot;$('#save-state').textContent='Could not load';}}
document.addEventListener('input',e=>{if(e.target.id==='ai-requirements'){aiRequirements=e.target.value;aiPrompt=creativePrompt();$('#ai-prompt').value=aiPrompt;}if(e.target.id==='ai-prompt')aiPrompt=e.target.value;if(e.target.id==='vendor-q'){vendorFilter.q=e.target.value;renderVendorGrid();}});
const bridge=createCreativeBridge({getOwner:()=>user?.id,onStatus:text=>{bridgeStatus=text;if($('#bridge-status'))$('#bridge-status').textContent=text;},receive:async m=>{
 const session=isLocalUser()?{user}:await api('/api/session');if(session.user?.id!==user?.id)throw Error('Your signed-in account changed. Reload before importing.');
 if(!state.designs.some(d=>d.jobId===m.id)){const file=new File([m.blob],m.name+(m.mode==='video'?'.mp4':'.png'),{type:m.blob.type});const result=await upload(file,m.mode==='video'?'/api/videos':'/api/assets');state.designs.push({id:uid(),jobId:m.id,name:m.name,mode:m.mode,provider:m.provider,format:m.mode==='video'?'AI video':'AI artwork',url:result.url,created:new Date().toISOString()});changed();}
 await flushSave();go('designs');toast('Your '+m.mode+' is saved to your collection.');
}});
async function flushSave(){for(let i=0;saving&&i<100;i++)await new Promise(r=>setTimeout(r,100));if(saving)throw Error('A save is still in progress. Try returning the result again.');await save();for(let i=0;saving&&i<100;i++)await new Promise(r=>setTimeout(r,100));if(dirty||saving)throw Error('Your result is on this page but could not be saved. Resolve the save error and retry the return.');}
async function sendCreative(el){if(!selectedEvent())throw Error('Add a wedding event first.');const prompt=$('#ai-prompt').value.trim();if(!prompt||prompt.length>14000)throw Error('Enter a design prompt between 1 and 14,000 characters.');if(aiMode==='video'&&(!state.profile.photo1||!state.profile.photo2))throw Error('Upload both partner photos for your video brief.');if(!bridge.ready)throw Error('Install the companion on desktop Chrome or Edge, then reload this page.');el.disabled=true;try{aiPrompt=prompt;const photos=aiMode==='image'&&aiReference==='event'&&(selectedEvent()?.cardPhoto||state.profile.invitationPhoto)?[await referencePhoto(selectedEvent().cardPhoto||state.profile.invitationPhoto,'couple-reference')]:await Promise.all([['photo1','partner-one-reference'],['photo2','partner-two-reference']].filter(([key])=>state.profile[key]).map(([key,name])=>referencePhoto(state.profile[key],name)));await bridge.start({id:uid(),owner:user.id,provider:aiProvider,mode:aiMode,prompt:aiPrompt,photos,name:selectedEvent().name+' · '+couple()});}finally{el.disabled=false;}}
